using System;
using System.Linq;
using EchoStation.Puzzles;
using EchoStation.Story;
using NUnit.Framework;
namespace EchoStation.Tests.Puzzles
{
 public sealed class ProgressAuditTests
 {
  private static ProgressState Empty()=>new ProgressState{Events=new[]{"visited_valley"}};
  private static ProgressState Full()=>new ProgressState{Completed=StationScript.Puzzles.Select(p=>p.Id).ToArray(),Journal=StationClues.All.Select(c=>c.Id).ToArray(),Scans=new[]{"scan_mark_01","scan_lab_calibration_01"},Events=StationScript.Puzzles.Select(p=>p.CompletionId).Concat(new[]{"visited_core"}).ToArray(),Zone="core",AccessLevel=3,CabinOpen=true,CoreOpen=true,VentOpen=true,Powered=true,VentElapsed=3};
  [Test]public void F01_A01_EmptyFullAndBacktrackingAreValid(){Assert.That(ProgressAudit.Validate(Empty()),Is.Null);var full=Full();Assert.That(ProgressAudit.Validate(full),Is.Null);full.Zone="valley";full.AccessLevel=0;full.Events=full.Events.Concat(new[]{"visited_valley"}).ToArray();Assert.That(ProgressAudit.Validate(full),Is.Null);}
  [Test]public void F01_A02_MissingPrerequisiteAndEventsRejectWithoutMutation(){var s=Full();s.Completed=s.Completed.Where(id=>id!="pz03").ToArray();var before=(string[])s.Completed.Clone();Assert.That(ProgressAudit.Validate(s),Is.EqualTo("invalid_prerequisite"));Assert.That(s.Completed,Is.EqualTo(before));s=Full();s.Events=s.Events.Where(id=>id!="progress_pz06").ToArray();Assert.That(ProgressAudit.Validate(s),Is.EqualTo("progress_event_mismatch"));}
  [Test]public void F01_A03_GuessedCabinCodeDoesNotRequireOrInventPasswordNote(){var s=Empty();s.Completed=new[]{"pz02"};s.Journal=new[]{"terminal_data_01"};s.Events=new[]{"visited_valley","progress_pz02"};Assert.That(ProgressAudit.Validate(s),Is.Null);s.Journal=Array.Empty<string>();Assert.That(ProgressAudit.Validate(s),Is.EqualTo("terminal_receipt_mismatch"));}
  [Test]public void F01_A04_HiddenAndCredentialForgeryReject(){var s=Empty();s.Journal=new[]{"scan_mark_01"};Assert.That(ProgressAudit.Validate(s),Is.EqualTo("hidden_scan_mismatch"));s=Full();s.Scans=new[]{"scan_mark_01"};Assert.That(ProgressAudit.Validate(s),Is.EqualTo("hidden_scan_mismatch"));s=Full();s.Completed=s.Completed.Where(id=>id!="pz06").ToArray();s.Events=s.Events.Where(id=>id!="progress_pz06").ToArray();s.Journal=s.Journal.Where(id=>id!="note_evacuation_01").ToArray();Assert.That(ProgressAudit.Validate(s),Is.EqualTo("missing_evidence"));}
  [Test]public void F01_A05_DeviceScansNeedMatchingJournalAndKnownIds(){var s=Empty();s.Scans=new[]{"power_panel_01"};Assert.That(ProgressAudit.Validate(s),Is.EqualTo("scan_journal_mismatch"));s.Journal=new[]{"power_panel_01"};Assert.That(ProgressAudit.Validate(s),Is.Null);s.Journal=new[]{"unknown_01"};Assert.That(ProgressAudit.Validate(s),Is.EqualTo("unknown_source"));}
  [Test]public void F01_A06_DoorsAndPhysicalThresholdsRejectPrematureAccess(){var s=Empty();s.CabinOpen=true;Assert.That(ProgressAudit.Validate(s),Is.EqualTo("unauthorized_door"));s=Empty();s.Zone="lab_a";s.Events=new[]{"visited_lab_a"};Assert.That(ProgressAudit.Validate(s),Is.Null,"Descriptive zone begins before physical door");s.AccessLevel=1;Assert.That(ProgressAudit.Validate(s),Is.EqualTo("inaccessible_position"));s=Full();s.CoreOpen=false;Assert.That(ProgressAudit.Validate(s),Is.EqualTo("inaccessible_position"));}
  [Test]public void F01_A07_MidVentilationOnlyValidBeforeBarrier(){var s=new ProgressState{Completed=new[]{"pz02","pz03"},Journal=new[]{"terminal_data_01"},Events=new[]{"progress_pz02","progress_pz03","visited_lab_a"},AccessLevel=1,Zone="lab_a",CabinOpen=true,Powered=true,VentElapsed=1.2f};Assert.That(ProgressAudit.Validate(s),Is.Null);s.VentOpen=true;Assert.That(ProgressAudit.Validate(s),Is.EqualTo("ventilation_mismatch"));s.VentElapsed=float.NaN;Assert.That(ProgressAudit.Validate(s),Is.EqualTo("ventilation_mismatch"));s=Full();s.VentElapsed=1;s.VentOpen=false;Assert.That(ProgressAudit.Validate(s),Is.EqualTo("ventilation_mismatch"));}
  [Test]public void F01_A08_UnknownZoneDuplicateNullAndCapacityReject(){Assert.That(ProgressAudit.Validate(null),Is.EqualTo("missing_state"));var s=Empty();s.Zone="space";Assert.That(ProgressAudit.Validate(s),Is.EqualTo("zone_mismatch"));s=Empty();s.Scans=new[]{"scan_mark_01","scan_mark_01"};Assert.That(ProgressAudit.Validate(s),Is.EqualTo("invalid_ids"));s=Empty();s.Events=Enumerable.Range(0,513).Select(i=>"event_"+i).ToArray();Assert.That(ProgressAudit.Validate(s),Is.EqualTo("invalid_ids"));}
 }
}
